package com.bank.legacy.service;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Generates all palindrome partitionings of a reference token via backtracking.
public class PartitionService {
    private static final Logger log = Logger.getLogger(PartitionService.class.getName());

    public List<List<String>> palindromePartitions(String token) {
        List<List<String>> result = new ArrayList<>();
        backtrack(token, 0, new ArrayList<>(), result);
        log.info(() -> "Generated " + result.size() + " palindrome partitions");
        return result;
    }

    private void backtrack(String token, int start,
                           List<String> current, List<List<String>> result) {
        if (start == token.length()) {
            result.add(new ArrayList<>(current)); // whole token consumed
            log.fine(() -> "Partition " + current);
            return;
        }
        for (int end = start; end < token.length(); end++) {
            if (isPalindrome(token, start, end)) {
                current.add(token.substring(start, end + 1)); // accept palindromic piece
                backtrack(token, end + 1, current, result);   // split the remainder
                current.remove(current.size() - 1);           // backtrack
            }
        }
    }

    private boolean isPalindrome(String s, int lo, int hi) {
        while (lo < hi) {
            if (s.charAt(lo) != s.charAt(hi)) {
                return false;
            }
            lo++;
            hi--;
        }
        return true;
    }
}
