package com.bank.legacy;

import com.bank.legacy.service.PartitionService;
import java.util.logging.Logger;

public class PartitionApplication {
    private static final Logger log = Logger.getLogger(PartitionApplication.class.getName());

    public static void main(String[] args) {
        PartitionService service = new PartitionService();
        // Token "aab" → [[a, a, b], [aa, b]].
        log.info("NBI token 'aab' palindrome partitions: "
                + service.palindromePartitions("aab"));
    }
}
